"use client";

import { useState, useEffect } from "react";
import { supabase } from "@/lib/supabase";
import { useRouter, usePathname } from "next/navigation";
import Link from "next/link";
import {
  Loader2,
  LayoutDashboard,
  ShoppingBag,
  ShoppingCart,
  Bell,
  Settings,
  LogOut,
  Menu,
  X,
  Crown,
  BadgeCheck,
  Coins,
} from "lucide-react";
import { effectiveSellerTier } from "@/utils/marketplaceDiscovery";
import { fetchOnboardingContext, getOnboardingHubRedirect } from "@/lib/onboardingState";
import OnboardingProgressCard from "@/components/onboarding/OnboardingProgressCard";
import { getMissingOnboardingFields } from "@/lib/onboardingChecklist";

export default function DashboardLayout({ children }: { children: React.ReactNode }) {
  const router = useRouter();
  const pathname = usePathname();

  const [loading, setLoading] = useState(true);
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [effectivePlan, setEffectivePlan] = useState<"standard" | "diamond">("standard");
  const [unreadCount, setUnreadCount] = useState(0);
  const [onboardingPath, setOnboardingPath] = useState<string | null>(null);
  const [missingFields, setMissingFields] = useState<string[]>([]);

  useEffect(() => {
    let cancelled = false;
    let notifyChannel: ReturnType<typeof supabase.channel> | null = null;

    const checkAuthAndData = async () => {
      const { data: { user } } = await supabase.auth.getUser();
      if (!user) {
        router.push("/login");
        return;
      }

      const [storeRes, notifyRes] = await Promise.all([
        supabase.from("stores").select("subscription_expiry, subscription_plan, subscription_status, slug, location").eq("owner_id", user.id).maybeSingle(),
        supabase.from("notifications").select("*", { count: "exact", head: true }).eq("user_id", user.id).eq("is_read", false),
      ]);
      const { data: profile } = await supabase
        .from("profiles")
        .select(
          "full_name, phone_number, slug, location_state, location_city, location, is_seller, onboarding_completed, onboarding_step, buyer_interested_categories"
        )
        .eq("id", user.id)
        .maybeSingle();
      const ctx = await fetchOnboardingContext(supabase, user.id);
      const postLoginPath = getOnboardingHubRedirect(ctx);
      setOnboardingPath(postLoginPath.startsWith("/onboarding") ? postLoginPath : null);
      setMissingFields(getMissingOnboardingFields(profile as any, Boolean((profile as any)?.is_seller), storeRes.data as any));

      if (cancelled) return;

      if (storeRes.data?.subscription_plan != null) {
        setEffectivePlan(
          effectiveSellerTier(
            storeRes.data.subscription_plan,
            storeRes.data.subscription_expiry,
            storeRes.data.subscription_status
          )
        );
      }

      setUnreadCount(notifyRes.count || 0);

      notifyChannel = supabase
        .channel(`user-notifications-${user.id}`)
        .on(
          "postgres_changes",
          { event: "INSERT", schema: "public", table: "notifications", filter: `user_id=eq.${user.id}` },
          () => {
            setUnreadCount((prev) => prev + 1);
          }
        )
        .subscribe();

      setLoading(false);
    };

    checkAuthAndData();

    return () => {
      cancelled = true;
      if (notifyChannel) supabase.removeChannel(notifyChannel);
    };
  }, [router]);

  const handleLogout = async () => {
    await supabase.auth.signOut();
    window.location.assign("/login");
  };

  const planHint =
    effectivePlan === "diamond"
      ? "Diamond visibility boost active"
      : "Standard — free storefront";

  const links = [
    { name: "Overview", href: "/dashboard", icon: LayoutDashboard },
    { name: "My purchases", href: "/account/orders", icon: ShoppingCart },
    { name: "Orders", href: "/dashboard/orders", icon: ShoppingBag },
    { name: "Notifications", href: "/dashboard/notifications", icon: Bell, badge: unreadCount > 0 ? unreadCount : null },
    { name: "Store Coin loyalty", href: "/dashboard/loyalty", icon: Coins, isNew: true, color: "text-amber-500" },
    { name: "Visibility & plans", href: "/dashboard/subscription", icon: Crown },
    { name: "Verification", href: "/dashboard/verification", icon: BadgeCheck },
    { name: "Settings", href: "/dashboard/settings", icon: Settings },
  ];

  if (loading) {
    return (
      <div className="h-screen flex items-center justify-center bg-gray-50">
        <Loader2 className="animate-spin text-gray-400" />
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-gray-50">
      <div className="md:hidden fixed top-0 left-0 right-0 bg-white border-b border-gray-200 p-4 flex justify-between items-center z-30">
        <Link href="/" className="font-extrabold text-lg text-gray-900 flex items-center gap-2">
          <LayoutDashboard className="text-emerald-600" size={20} /> StoreLink
        </Link>
        <div className="flex items-center gap-2">
          {unreadCount > 0 && (
            <Link href="/dashboard/notifications" className="p-2 bg-red-50 rounded-lg text-red-600 relative">
              <Bell size={20} />
              <span className="absolute top-1 right-1 w-2 h-2 bg-red-500 rounded-full border border-white" />
            </Link>
          )}
          <button onClick={() => setIsMobileMenuOpen(true)} className="p-2 text-gray-700 hover:bg-gray-100 rounded-lg">
            <Menu size={24} />
          </button>
        </div>
      </div>

      {isMobileMenuOpen && (
        <div className="fixed inset-0 z-50 md:hidden">
          <div className="absolute inset-0 bg-black/50 backdrop-blur-sm transition-opacity" onClick={() => setIsMobileMenuOpen(false)} />
          <div className="absolute inset-y-0 left-0 w-64 bg-white border-r border-gray-200 flex flex-col shadow-2xl animate-in slide-in-from-left duration-200 overflow-y-auto">
            <div className="p-6 border-b border-gray-100 flex justify-between items-center">
              <span className="font-black text-xl text-gray-900">Menu</span>
              <button onClick={() => setIsMobileMenuOpen(false)} className="p-2 text-gray-500 hover:bg-gray-100 rounded-lg">
                <X size={24} />
              </button>
            </div>
            <nav className="flex-1 p-4 space-y-2">
              {links.map((link) => {
                const isActive = pathname === link.href;
                const Icon = link.icon;
                return (
                  <Link
                    key={link.href}
                    href={link.href}
                    onClick={() => setIsMobileMenuOpen(false)}
                    className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-bold text-sm ${isActive ? "bg-emerald-50 text-emerald-600" : "text-gray-500 hover:bg-gray-50 hover:text-gray-900"}`}
                  >
                    <div className="relative">
                      <Icon size={18} className={link.color ? link.color : ""} />
                      {link.badge && <span className="absolute -top-1 -right-1 w-2 h-2 bg-red-500 rounded-full animate-pulse" />}
                    </div>
                    <span>{link.name}</span>
                    {link.badge && (
                      <span className="ml-auto bg-red-100 text-red-600 text-[10px] px-2 py-0.5 rounded-full">{link.badge}</span>
                    )}
                  </Link>
                );
              })}
            </nav>

            <div className="mx-4 mb-4 p-3 bg-emerald-50/80 border border-emerald-100 rounded-xl">
              <p className="text-[9px] font-bold text-emerald-800 uppercase tracking-widest leading-relaxed">{planHint}</p>
              <p className="text-[9px] text-emerald-700/80 mt-1 leading-snug">Your link stays online on Standard. Upgrade anytime for extra visibility.</p>
            </div>

            <div className="p-4 border-t border-gray-100">
              <button
                onClick={handleLogout}
                className="flex items-center gap-3 px-4 py-3 w-full text-left text-red-500 hover:bg-red-50 rounded-xl transition-all text-sm font-bold"
              >
                <LogOut size={18} /> Logout
              </button>
            </div>
          </div>
        </div>
      )}

      <aside className="w-64 bg-white border-r border-gray-200 hidden md:flex flex-col fixed h-screen top-0 overflow-y-auto z-20 no-scrollbar">
        <div className="p-6 border-b border-gray-100 shrink-0">
          <Link href="/" className="font-extrabold text-xl text-gray-900 flex items-center gap-2 tracking-tight">
            <LayoutDashboard className="text-emerald-600" size={24} /> StoreLink
          </Link>
        </div>

        <nav className="flex-1 p-4 space-y-2">
          {links.map((link) => {
            const isActive = pathname === link.href;
            const Icon = link.icon;
            return (
              <Link
                key={link.href}
                href={link.href}
                className={`flex items-center gap-3 px-4 py-3 rounded-xl transition-all font-bold text-sm ${isActive ? "bg-emerald-50 text-emerald-600" : "text-gray-500 hover:bg-gray-50 hover:text-gray-900"}`}
              >
                <div className="relative">
                  <Icon size={18} className={link.color ? link.color : ""} />
                  {link.badge && (
                    <span className="absolute -top-1.5 -right-1.5 flex h-3 w-3">
                      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-red-400 opacity-75"></span>
                      <span className="relative inline-flex rounded-full h-3 w-3 bg-red-500 border border-white"></span>
                    </span>
                  )}
                </div>
                <span>{link.name}</span>
                {link.badge && (
                  <span className="ml-auto bg-red-500 text-white text-[10px] font-black px-1.5 py-0.5 rounded-md">{link.badge}</span>
                )}
                {link.isNew && !isActive && !link.badge && (
                  <span className="ml-auto bg-amber-100 text-amber-600 text-[8px] font-black px-1.5 py-0.5 rounded-md animate-pulse">NEW</span>
                )}
              </Link>
            );
          })}
        </nav>

        <div className="mx-4 mb-2 p-3 rounded-xl border bg-emerald-50/50 border-emerald-100">
          <p className="text-[10px] font-black text-emerald-800 uppercase tracking-widest leading-relaxed">{planHint}</p>
          <p className="text-[9px] text-emerald-800/75 mt-1 leading-snug">Standard is free forever. Upgrade for marketplace visibility boosts.</p>
        </div>

        <div className="p-4 border-t border-gray-100 shrink-0">
          <button
            onClick={handleLogout}
            className="flex items-center gap-3 px-4 py-3 w-full text-left text-red-500 hover:bg-red-50 rounded-xl transition-all text-sm font-bold"
          >
            <LogOut size={18} /> Logout
          </button>
        </div>
      </aside>

      <main className="flex-1 md:ml-64 p-4 md:p-8 pt-20 md:pt-8 w-full max-w-full overflow-hidden flex flex-col gap-4">
        <OnboardingProgressCard continueHref={onboardingPath} missingFields={missingFields} />
        {children}
      </main>
    </div>
  );
}
